import {GamepadHub,padAxis,padButton} from '../3d/index.js';
import {bindPointers,pointerPoint} from '../shared/pointers.js';
export function createCreativeInput(root,{kind,count,model,enabled,pause,help,getPads=()=>navigator.getGamepads?.()||[]}){const keys=new Set(),hands=new Map(),lures=new Map(),touch=Array.from({length:count},()=>({x:0,z:0,alt:0,boost:false,brake:false,dock:false})),pressed=new Map();let owner=0;const hub=new GamepadHub({players:count,onDisconnect(){cancel();pause();}}),clean=[];
 const listen=(target,event,fn)=>{target.addEventListener(event,fn);clean.push(()=>target.removeEventListener(event,fn));};
 function cancel(){keys.clear();hands.clear();for(const t of touch)Object.assign(t,{x:0,z:0,alt:0,boost:false,brake:false,dock:false});for(let i=0;i<count;i++)if(kind==='inkfin')model.lure(i,model.lures[i].x,model.lures[i].y,false);for(const p of lures.values())p.cancel();hub.clear();}
 listen(window,'keydown',e=>{if(!enabled()||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['Escape','KeyP'].includes(e.code)){e.preventDefault();pause();return;}if(['KeyW','KeyA','KeyS','KeyD','KeyQ','KeyE','KeyF','Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','PageUp','PageDown','Enter','ShiftRight','ShiftLeft'].includes(e.code)){e.preventDefault();keys.add(e.code);}});listen(window,'keyup',e=>keys.delete(e.code));
 for(const el of root.querySelectorAll('[data-flight-stick]')){const i=+el.dataset.flightStick,binding=bindPointers(el,{enabled,maxPointers:1,down(c){hands.set(c.id,i);return i;},move(c,e){const r=el.getBoundingClientRect();touch[i].x=Math.max(-1,Math.min(1,(e.clientX-r.left-r.width/2)/(r.width*.38)));touch[i].z=Math.max(-1,Math.min(1,(e.clientY-r.top-r.height/2)/(r.height*.38)));},up(c){hands.delete(c.id);touch[i].x=touch[i].z=0;},cancel(c){hands.delete(c.id);touch[i].x=touch[i].z=0;}});lures.set(el,binding);}
 for(const el of root.querySelectorAll('[data-flight-action]')){const i=+el.dataset.owner,action=el.dataset.flightAction,binding=bindPointers(el,{enabled,maxPointers:1,down(){if(action==='up'||action==='down')touch[i].alt=action==='up'?1:-1;else touch[i][action]=true;},up(){if(action==='up'||action==='down')touch[i].alt=0;else touch[i][action]=false;},cancel(){if(action==='up'||action==='down')touch[i].alt=0;else touch[i][action]=false;}});lures.set(el,binding);el.onclick=e=>{if(e.detail===0&&enabled()&&action==='dock')model.dock(i);};}
 if(kind==='inkfin'){const canvas=root.querySelector('canvas'),binding=bindPointers(canvas,{enabled,maxPointers:count,down(c,e){const point=pointerPoint(canvas,e,{width:1000,height:560}),preferred=e.pointerType==='mouse'?owner:count===2&&point.x>500?1:0;if([...hands.values()].includes(preferred))return null;hands.set(c.id,preferred);model.lure(preferred,point.x,point.y,true,!!root.querySelector(`[data-repel="${preferred}"]`)?.checked);return preferred;},move(c,e){if(c.data===null)return;const p=pointerPoint(canvas,e,{width:1000,height:560});model.lure(c.data,p.x,p.y,true,!!root.querySelector(`[data-repel="${c.data}"]`)?.checked);},up(c){if(c.data!==null){model.lure(c.data,model.lures[c.data].x,model.lures[c.data].y,false);hands.delete(c.id);}},cancel(c){if(c.data!==null){model.lure(c.data,model.lures[c.data].x,model.lures[c.data].y,false);hands.delete(c.id);}}});lures.set(canvas,binding);for(const b of root.querySelectorAll('[data-lure-owner]'))b.onclick=()=>{owner=+b.dataset.lureOwner;root.querySelectorAll('[data-lure-owner]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));};}
 function tick(dt){hub.poll(getPads(),enabled()?'play':'menus');const intents=[];for(let i=0;i<count;i++){if(enabled()&&hub.pressed(i,9)){pause();return[];}if(enabled()&&hub.pressed(i,8)){help();return[];}const p=hub.pad(i),has=!!p&&!hub.slots[i]?.neutral,t=touch[i],k=i?['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','PageDown','PageUp','Enter','ShiftRight']:['KeyA','KeyD','KeyW','KeyS','KeyQ','KeyE','KeyF','Space'];if(!enabled())continue;const intent={x:(keys.has(k[1])?1:0)-(keys.has(k[0])?1:0)+(has?padAxis(p,0):0)+t.x,z:(keys.has(k[3])?1:0)-(keys.has(k[2])?1:0)+(has?padAxis(p,1):0)+t.z,alt:(keys.has(k[5])?1:0)-(keys.has(k[4])?1:0)+(has?-padAxis(p,3):0)+t.alt,boost:keys.has(k[7])||t.boost||has&&padButton(p,2),dock:keys.has(k[6])||t.dock||has&&hub.pressed(i,0),brake:t.brake||keys.has('ShiftLeft')||has&&padButton(p,1)};intents.push(intent);if(kind==='inkfin'&&!handsHas(i)&&(has||keys.size)){const l=model.lures[i],active=has&&(padButton(p,0)||padButton(p,7))||keys.has(k[6]),repel=has&&padButton(p,1)||keys.has(k[7]);model.lure(i,l.x+intent.x*dt*280,l.y+intent.z*dt*280,active,repel);}}return intents;}
 const handsHas=i=>[...hands.values()].includes(i);return{hub,touch,tick,cancel,dispose(){cancel();for(const p of lures.values())p.dispose();for(const fn of clean)fn();hub.dispose();}};
}
